  add(qMC(TV, 'Which parameter does a microsomal stability assay yield before any scaling?', 'The in vitro half-life, converted to CLint in microL/min/mg of protein.', ['The fraction unbound in plasma.', 'The apparent permeability.', 'The volume of distribution.'], 'A microsomal stability assay follows the loss of the compound over time. The fraction unbound, the permeability and the volume come from other assays or from in vivo data.'), function(){ return { name: 'flow', o: { w: 600, h: 190, boxes: [{ x: 10, y: 20, w: 170, h: 40, t: 'Microsomal stability', f: '#EDF2F4', fs: 11 }, { x: 10, y: 75, w: 170, h: 40, t: 'Equilibrium dialysis', f: '#EDF2F4', fs: 11 }, { x: 10, y: 130, w: 170, h: 40, t: 'Caco-2 monolayer', f: '#EDF2F4', fs: 11 }, { x: 420, y: 20, w: 170, h: 40, t: 'Parameter A', f: '#fff', d: '5 4', fs: 11 }, { x: 420, y: 75, w: 170, h: 40, t: 'Parameter B', f: '#fff', d: '5 4', fs: 11 }, { x: 420, y: 130, w: 170, h: 40, t: 'Parameter C', f: '#fff', d: '5 4', fs: 11 }], arrows: [[180, 40, 420, 40], [180, 95, 420, 95], [180, 150, 420, 150]], cap: 'Assays and the parameters they yield' } }; });
